/**
 * Sprint 35R — Decision Support User-Visible Dry Run Evaluation Harness: fixtures.
 *
 * Scenario descriptors used by
 * `tests/playbook-engine-conversation-decision-support-user-visible-dry-run-evaluation-harness.test.mjs`.
 * Each entry documents one behavior this sprint must exhibit — some carry a `sourceQualityCaseEvaluation`
 * (a minimal `{ caseId, draftId, draftKind, sourceRouteKind, sourceResponseKind, overallScore }` shape —
 * exactly the fields `renderDecisionSupportUserVisibleDryRunPreview()` and
 * `createDecisionSupportUserVisibleDryRunDisplayContract()` read off a real Sprint 34R
 * `DecisionSupportResponseDraftQualityCaseEvaluation`) that the test file feeds through those functions
 * plus `validateDecisionSupportUserVisibleDryRunPreview()`; others (e.g. "attempt to enable X blocked")
 * describe a config-level invariant the test file checks directly, and use neutral placeholders for the
 * fields that do not apply.
 *
 * This fixture never imports from `src/`, and is never imported by production code — it exists only for
 * this sprint's own test suite.
 */

export type DecisionSupportUserVisibleDryRunFixtureSourceCase = {
  caseId: string;
  draftId: string;
  draftKind: string;
  sourceRouteKind: string;
  sourceResponseKind: string;
  overallScore: number;
};

export type DecisionSupportUserVisibleDryRunFixtureCase = {
  id: string;
  scenario: string;
  previewKind: string;
  expectedQaStatus: string;
  expectedRiskLevel: string;
  expectedValid: boolean;
  expectedDisplayContractStatus: string;
  expectedPreviewQualityScoreRange: [number, number];
  expectedDisplayContractScoreRange: [number, number];
  expectedSafeForDefaultOffRouteComposerAdapter: boolean;
  expectedSafeForUserVisibleOutputNow: boolean;
  expectedSafeForProduction: boolean;
  expectedViolations: string[];
  notes: string;
  /** Present only for scenarios that render/validate a real synthetic preview. */
  sourceQualityCaseEvaluation?: DecisionSupportUserVisibleDryRunFixtureSourceCase;
  /** Present only for the thirteen "attempt to enable X blocked" config scenarios. */
  configOverrideField?:
    | "allowUserVisibleOutput"
    | "allowProductionWiring"
    | "allowRouterChange"
    | "allowComposerChange"
    | "allowEndpointChange"
    | "allowFeatureFlag"
    | "allowRealPersistence"
    | "allowDbWrite"
    | "allowSupabaseWrite"
    | "allowExternalCalls"
    | "allowActionExecution"
    | "allowTaskCreation"
    | "allowEmailDraftCreation";
};

